import { useState, useMemo, useEffect } from 'react';
import { loadBulkIds, saveBulkIds, loadOrders, saveOrders, clearAllData } from './storage';

const TABS = ['Dashboard', 'Stock Manager', 'New Order', 'Order History'];

const fmtK = (n) => {
  if (n >= 1000) { const k = n / 1000; return (k % 1 === 0 ? k : k.toFixed(1)) + 'K'; }
  return String(n);
};
const parseK = (val) => { const s = String(val).trim().toLowerCase(); if (s.endsWith('k')) return parseFloat(s) * 1000; return parseFloat(s); };
const fmtMoney = (n) => `$${Number(n).toFixed(2)}`;
const stockColor = (used, total) => { const p = total > 0 ? used / total : 0; if (p >= 0.9) return '#ff4d4d'; if (p >= 0.6) return '#ffaa00'; return '#00e5a0'; };

export default function App() {
  const [bulkGroups, setBulkGroupsRaw] = useState([]);
  const [orders, setOrdersRaw] = useState([]);
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [orderForm, setOrderForm] = useState({ customerGameId: '', quantity: '' });
  const [orderResult, setOrderResult] = useState(null);
  const [notif, setNotif] = useState(null);
  const [showAdd, setShowAdd] = useState(false);
  const [addMode, setAddMode] = useState('range');
  const [rangeForm, setRangeForm] = useState({ prefix: 'vivopop', from: '1', to: '100', stockPerId: '15', pricePerUnit: '0.05' });
  const [singleForm, setSingleForm] = useState({ id: '', stockPerId: '', pricePerUnit: '' });
  const [showClear, setShowClear] = useState(false);
  const [search, setSearch] = useState('');
  const [expandedGroup, setExpandedGroup] = useState(null);

  useEffect(() => {
    const raw = loadBulkIds();
    if (raw.length > 0 && raw[0].ids) {
      setBulkGroupsRaw(raw);
    } else if (raw.length > 0) {
      const migrated = raw.map(b => ({ groupId: b.id, prefix: b.id, from: 1, to: 1, ids: [{ id: b.id, totalStock: b.totalStock, usedStock: b.usedStock }], pricePerUnit: b.pricePerUnit, label: b.label || b.id }));
      setBulkGroupsRaw(migrated);
    }
    setOrdersRaw(loadOrders());
  }, []);

  const setBulkGroups = (fn) => setBulkGroupsRaw(prev => { const next = typeof fn === 'function' ? fn(prev) : fn; saveBulkIds(next); return next; });
  const setOrders = (fn) => setOrdersRaw(prev => { const next = typeof fn === 'function' ? fn(prev) : fn; saveOrders(next); return next; });
  const notify = (msg, type = 'success') => { setNotif({ msg, type }); setTimeout(() => setNotif(null), 3500); };

  const allIds = useMemo(() => bulkGroups.flatMap(g => g.ids.map(id => ({ ...id, pricePerUnit: g.pricePerUnit, groupId: g.groupId }))), [bulkGroups]);

  const stats = useMemo(() => {
    const totalStock = allIds.reduce((a, b) => a + b.totalStock, 0);
    const usedStock = allIds.reduce((a, b) => a + b.usedStock, 0);
    return { totalStock, usedStock, available: totalStock - usedStock, totalEarnings: orders.reduce((a, o) => a + o.earnings, 0), totalGroups: bulkGroups.length, totalIds: allIds.length };
  }, [allIds, orders, bulkGroups]);

  const getBest = (qty) => allIds.filter(b => b.totalStock - b.usedStock >= qty).sort((a, b) => (b.totalStock - b.usedStock) - (a.totalStock - a.usedStock))[0];

  const handleAddRange = () => {
    const { prefix, from, to, stockPerId, pricePerUnit } = rangeForm;
    const fromN = parseInt(from), toN = parseInt(to);
    const stockN = parseFloat(stockPerId) * 1000;
    const priceN = parseFloat(pricePerUnit);
    if (!prefix || isNaN(fromN) || isNaN(toN) || isNaN(stockN) || isNaN(priceN)) { notify('Fill all fields.', 'error'); return; }
    if (toN < fromN) { notify('End must be >= Start.', 'error'); return; }
    if (toN - fromN > 999) { notify('Max 1000 IDs per range.', 'error'); return; }
    const groupId = `${prefix}${fromN}-${prefix}${toN}`;
    if (bulkGroups.find(g => g.groupId === groupId)) { notify('Range already exists!', 'error'); return; }
    const ids = [];
    for (let i = fromN; i <= toN; i++) ids.push({ id: `${prefix}${i}`, totalStock: stockN, usedStock: 0 });
    setBulkGroups(prev => [...prev, { groupId, prefix, from: fromN, to: toN, ids, pricePerUnit: priceN, label: groupId }]);
    setShowAdd(false);
    notify(`Added ${ids.length} IDs (${prefix}${fromN} → ${prefix}${toN}) with ${stockPerId}K each!`);
  };

  const handleAddSingle = () => {
    const { id, stockPerId, pricePerUnit } = singleForm;
    const stockN = parseFloat(stockPerId) * 1000;
    const priceN = parseFloat(pricePerUnit);
    if (!id || isNaN(stockN) || isNaN(priceN)) { notify('Fill all fields.', 'error'); return; }
    if (allIds.find(b => b.id === id)) { notify('ID already exists.', 'error'); return; }
    setBulkGroups(prev => [...prev, { groupId: id, prefix: id, from: 1, to: 1, ids: [{ id, totalStock: stockN, usedStock: 0 }], pricePerUnit: priceN, label: id }]);
    setSingleForm({ id: '', stockPerId: '', pricePerUnit: '' });
    setShowAdd(false);
    notify(`Added ${id} with ${stockPerId}K stock!`);
  };

  const handleDeleteGroup = (groupId) => {
    if (window.confirm(`Delete group "${groupId}"? All IDs will be removed.`)) {
      setBulkGroups(prev => prev.filter(g => g.groupId !== groupId));
      notify('Group deleted.');
    }
  };

  const handleOrder = () => {
    const qty = parseFloat(orderForm.quantity) * 1000;
    if (!orderForm.customerGameId.trim() || !qty || qty <= 0) { notify('Fill all fields.', 'error'); return; }
    const best = getBest(qty);
    if (!best) { notify('No single ID has enough stock!', 'error'); return; }
    const earnings = parseFloat((qty * best.pricePerUnit).toFixed(2));
    const newOrder = { id: `ORD-${String(orders.length + 1).padStart(4, '0')}`, customerGameId: orderForm.customerGameId, quantity: qty, bulkIdUsed: best.id, groupUsed: best.groupId, status: 'Fulfilled', date: new Date().toISOString().split('T')[0], earnings };
    setBulkGroups(prev => prev.map(g => g.groupId === best.groupId ? { ...g, ids: g.ids.map(id => id.id === best.id ? { ...id, usedStock: id.usedStock + qty } : id) } : g));
    setOrders(prev => [newOrder, ...prev]);
    setOrderResult({ order: newOrder, best });
    setOrderForm({ customerGameId: '', quantity: '' });
    notify(`Order fulfilled via ${best.id}!`);
  };

  const exportCSV = () => {
    const rows = ['Order ID,Customer Game ID,Quantity,Bulk ID Used,Group,Earnings,Date'];
    orders.forEach(o => rows.push(`${o.id},${o.customerGameId},${fmtK(o.quantity)},${o.bulkIdUsed},${o.groupUsed || ''},${o.earnings},${o.date}`));
    const blob = new Blob([rows.join('\n')], { type: 'text/csv' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
    a.download = `popstock_${new Date().toISOString().split('T')[0]}.csv`; a.click();
  };

  const filteredOrders = orders.filter(o =>
    o.customerGameId.toLowerCase().includes(search.toLowerCase()) ||
    o.id.toLowerCase().includes(search.toLowerCase()) ||
    (o.bulkIdUsed || '').toLowerCase().includes(search.toLowerCase())
  );

  const rangePreviewCount = parseInt(rangeForm.to) - parseInt(rangeForm.from) + 1;
  const rangePreviewTotal = (isNaN(rangePreviewCount) ? 0 : rangePreviewCount) * (parseFloat(rangeForm.stockPerId) || 0) * 1000;

  return (
    <div style={S.app}>
      <style>{css}</style>
      {notif && <div className={`notif ${notif.type === 'success' ? 'ns' : 'ne'}`}>{notif.msg}</div>}

      {/* HEADER */}
      <div style={S.header}>
        <div>
          <div style={S.logo}><span style={{ color: '#5b6fff' }}>POP</span>STOCK</div>
          <div style={S.sub}>Popularity Inventory Manager · All data saved locally on your PC</div>
        </div>
        <button className="btn-danger-sm" onClick={() => setShowClear(true)}>🗑 Clear All Data</button>
      </div>

      {/* TABS */}
      <div style={S.tabBar}>
        {TABS.map(t => (
          <button key={t} className={`tab-btn ${activeTab === t ? 'active' : ''}`} onClick={() => { setActiveTab(t); setOrderResult(null); }}>{t}</button>
        ))}
      </div>

      {/* CLEAR MODAL */}
      {showClear && (
        <div style={S.overlay}>
          <div style={S.modal}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#ff4d4d', marginBottom: 10 }}>⚠ Clear All Data?</div>
            <div style={{ color: '#9ba3cc', marginBottom: 20, fontSize: 14 }}>Permanently deletes all Bulk IDs, groups, orders and earnings.</div>
            <div style={{ display: 'flex', gap: 10 }}>
              <button className="btn-danger" onClick={() => { clearAllData(); setBulkGroupsRaw([]); setOrdersRaw([]); setShowClear(false); notify('All data cleared.'); }}>Yes, Delete Everything</button>
              <button className="btn-outline" onClick={() => setShowClear(false)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      <div style={S.content}>

        {/* ── DASHBOARD ── */}
        {activeTab === 'Dashboard' && (
          <div>
            <div style={S.grid4}>
              {[
                { label: 'TOTAL STOCK', value: fmtK(stats.totalStock), icon: '📦', color: '#5b6fff' },
                { label: 'AVAILABLE', value: fmtK(stats.available), icon: '✅', color: '#00e5a0' },
                { label: 'USED STOCK', value: fmtK(stats.usedStock), icon: '📤', color: '#ffaa00' },
                { label: 'TOTAL EARNINGS', value: fmtMoney(stats.totalEarnings), icon: '💰', color: '#ff4d4d' },
              ].map(s => (
                <div key={s.label} className="stat-card">
                  <div style={{ fontSize: 26, marginBottom: 8 }}>{s.icon}</div>
                  <div className="lbl">{s.label}</div>
                  <div style={{ fontSize: 26, fontWeight: 800, color: s.color, fontFamily: 'Space Mono, monospace' }}>{s.value}</div>
                </div>
              ))}
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 20 }}>
              <div className="card">
                <div className="card-title">BULK ID GROUPS — {stats.totalGroups} groups · {stats.totalIds} IDs</div>
                {bulkGroups.length === 0 && <div className="empty-msg">No groups yet. Go to Stock Manager to add.</div>}
                {bulkGroups.map(g => {
                  const gTotal = g.ids.reduce((a, b) => a + b.totalStock, 0);
                  const gUsed = g.ids.reduce((a, b) => a + b.usedStock, 0);
                  const gAvail = gTotal - gUsed;
                  const pct = gTotal > 0 ? gUsed / gTotal : 0;
                  const col = stockColor(gUsed, gTotal);
                  return (
                    <div key={g.groupId} style={{ marginBottom: 18 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                        <div>
                          <span className="mono" style={{ color: '#5b6fff', fontWeight: 700, fontSize: 13 }}>{g.groupId}</span>
                          <span style={{ marginLeft: 8, color: '#4a5278', fontSize: 11, fontFamily: 'Space Mono, monospace' }}>{g.ids.length} IDs · {fmtK(g.ids[0]?.totalStock || 0)}/ID</span>
                        </div>
                        <span className="mono" style={{ fontSize: 12, color: col }}>{fmtK(gAvail)} left</span>
                      </div>
                      <div className="progress-bar">
                        <div style={{ height: '100%', width: `${pct * 100}%`, background: col, borderRadius: 3 }} />
                      </div>
                      <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 3 }}>
                        <span className="mono" style={{ fontSize: 10, color: '#2a3050' }}>{(pct * 100).toFixed(1)}% used</span>
                        <span className="mono" style={{ fontSize: 10, color: '#2a3050' }}>${g.pricePerUnit}/unit</span>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="card">
                <div className="card-title">RECENT ORDERS</div>
                {orders.length === 0 && <div className="empty-msg">No orders yet.</div>}
                {orders.slice(0, 6).map(o => (
                  <div key={o.id} style={S.recentRow}>
                    <div>
                      <div className="mono" style={{ color: '#5b6fff', fontSize: 12, fontWeight: 700 }}>{o.id}</div>
                      <div style={{ fontSize: 12, color: '#6b7299', marginTop: 2 }}>{o.customerGameId}</div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <div className="mono" style={{ color: '#00e5a0', fontSize: 13 }}>{fmtMoney(o.earnings)}</div>
                      <div className="mono" style={{ fontSize: 11, color: '#2a3050' }}>{fmtK(o.quantity)}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* ── STOCK MANAGER ── */}
        {activeTab === 'Stock Manager' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <div>
                <div className="page-title">BULK ID GROUPS</div>
                <div className="mono" style={{ fontSize: 11, color: '#4a5278', marginTop: 4 }}>{stats.totalGroups} groups · {stats.totalIds} IDs · {fmtK(stats.available)} available</div>
              </div>
              <button className="btn-primary" onClick={() => setShowAdd(!showAdd)}>+ Add Bulk IDs</button>
            </div>

            {showAdd && (
              <div className="card" style={{ marginBottom: 20 }}>
                <div style={{ display: 'flex', gap: 10, marginBottom: 18 }}>
                  <button className={`mode-btn ${addMode === 'range' ? 'active' : ''}`} onClick={() => setAddMode('range')}>📦 Add Range (vivopop1–100)</button>
                  <button className={`mode-btn ${addMode === 'single' ? 'active' : ''}`} onClick={() => setAddMode('single')}>➕ Add Single ID</button>
                </div>

                {addMode === 'range' && (
                  <div>
                    <div className="card-title">ADD RANGE OF IDs</div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr 1fr', gap: 14, marginBottom: 14 }}>
                      {[
                        { key: 'prefix', label: 'PREFIX', ph: 'e.g. vivopop' },
                        { key: 'from', label: 'START NUMBER', ph: 'e.g. 1' },
                        { key: 'to', label: 'END NUMBER', ph: 'e.g. 100' },
                        { key: 'stockPerId', label: 'STOCK PER ID (K)', ph: 'e.g. 15' },
                        { key: 'pricePerUnit', label: 'PRICE/UNIT ($)', ph: 'e.g. 0.05' },
                      ].map(f => (
                        <div key={f.key}>
                          <div className="lbl">{f.label}</div>
                          <input value={rangeForm[f.key]} onChange={e => setRangeForm(p => ({ ...p, [f.key]: e.target.value }))} placeholder={f.ph} />
                        </div>
                      ))}
                    </div>
                    {/* PREVIEW */}
                    <div style={{ background: '#0d1020', borderRadius: 10, padding: '12px 16px', marginBottom: 14, fontFamily: 'Space Mono, monospace', fontSize: 12 }}>
                      <span style={{ color: '#4a5278' }}>Preview: </span>
                      <span style={{ color: '#5b6fff' }}>{rangeForm.prefix}{rangeForm.from}</span>
                      <span style={{ color: '#4a5278' }}> → </span>
                      <span style={{ color: '#5b6fff' }}>{rangeForm.prefix}{rangeForm.to}</span>
                      <span style={{ color: '#4a5278' }}> · </span>
                      <span style={{ color: '#00e5a0' }}>{isNaN(rangePreviewCount) || rangePreviewCount < 0 ? 0 : rangePreviewCount} IDs</span>
                      <span style={{ color: '#4a5278' }}> · </span>
                      <span style={{ color: '#ffaa00' }}>{rangeForm.stockPerId}K per ID</span>
                      <span style={{ color: '#4a5278' }}> · Total Stock: </span>
                      <span style={{ color: '#fff', fontWeight: 700 }}>{fmtK(rangePreviewTotal)}</span>
                    </div>
                    <div style={{ display: 'flex', gap: 10 }}>
                      <button className="btn-primary" onClick={handleAddRange}>Add Range</button>
                      <button className="btn-outline" onClick={() => setShowAdd(false)}>Cancel</button>
                    </div>
                  </div>
                )}

                {addMode === 'single' && (
                  <div>
                    <div className="card-title">ADD SINGLE BULK ID</div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 14, marginBottom: 14 }}>
                      {[
                        { key: 'id', label: 'BULK ID', ph: 'e.g. vivopop101' },
                        { key: 'stockPerId', label: 'STOCK (K)', ph: 'e.g. 15 = 15K' },
                        { key: 'pricePerUnit', label: 'PRICE/UNIT ($)', ph: 'e.g. 0.05' },
                      ].map(f => (
                        <div key={f.key}>
                          <div className="lbl">{f.label}</div>
                          <input value={singleForm[f.key]} onChange={e => setSingleForm(p => ({ ...p, [f.key]: e.target.value }))} placeholder={f.ph} />
                        </div>
                      ))}
                    </div>
                    <div style={{ display: 'flex', gap: 10 }}>
                      <button className="btn-primary" onClick={handleAddSingle}>Add ID</button>
                      <button className="btn-outline" onClick={() => setShowAdd(false)}>Cancel</button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {bulkGroups.length === 0 && <div className="card"><div className="empty-msg">No Bulk ID groups yet. Click "+ Add Bulk IDs".</div></div>}

            {bulkGroups.map(g => {
              const gTotal = g.ids.reduce((a, b) => a + b.totalStock, 0);
              const gUsed = g.ids.reduce((a, b) => a + b.usedStock, 0);
              const gAvail = gTotal - gUsed;
              const pct = gTotal > 0 ? gUsed / gTotal : 0;
              const col = stockColor(gUsed, gTotal);
              const status = pct >= 0.9 ? 'LOW' : pct >= 0.6 ? 'MID' : 'OK';
              const bc = pct >= 0.9 ? 'badge-red' : pct >= 0.6 ? 'badge-yellow' : 'badge-green';
              const isExp = expandedGroup === g.groupId;
              return (
                <div key={g.groupId} className="card" style={{ marginBottom: 12 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
                        <span className="mono" style={{ color: '#5b6fff', fontWeight: 700, fontSize: 15 }}>{g.groupId}</span>
                        <span className={`badge ${bc}`}>{status}</span>
                        <span className="mono" style={{ color: '#4a5278', fontSize: 11 }}>{g.ids.length} IDs · {fmtK(g.ids[0]?.totalStock || 0)}/ID</span>
                      </div>
                      <div style={{ display: 'flex', gap: 28 }}>
                        <div><div className="lbl">TOTAL STOCK</div><div className="mono" style={{ fontSize: 15 }}>{fmtK(gTotal)}</div></div>
                        <div><div className="lbl">USED</div><div className="mono" style={{ fontSize: 15, color: '#ffaa00' }}>{fmtK(gUsed)}</div></div>
                        <div><div className="lbl">AVAILABLE</div><div className="mono" style={{ fontSize: 15, color: col }}>{fmtK(gAvail)}</div></div>
                        <div><div className="lbl">PRICE/UNIT</div><div className="mono" style={{ fontSize: 15, color: '#9ba3cc' }}>${g.pricePerUnit}</div></div>
                      </div>
                      <div className="progress-bar" style={{ marginTop: 12 }}>
                        <div style={{ height: '100%', width: `${pct * 100}%`, background: col, borderRadius: 3 }} />
                      </div>
                      <div className="mono" style={{ fontSize: 10, color: '#2a3050', marginTop: 4 }}>{(pct * 100).toFixed(1)}% used</div>
                    </div>
                    <div style={{ display: 'flex', gap: 8, marginLeft: 20, marginTop: 4 }}>
                      <button className="btn-sm" onClick={() => setExpandedGroup(isExp ? null : g.groupId)}>{isExp ? '▲ Hide' : '▼ View IDs'}</button>
                      <button className="btn-sm-danger" onClick={() => handleDeleteGroup(g.groupId)}>Delete</button>
                    </div>
                  </div>

                  {isExp && (
                    <div style={{ marginTop: 16, borderTop: '1px solid #1a2040', paddingTop: 14 }}>
                      <div className="lbl" style={{ marginBottom: 10 }}>ALL IDs IN THIS GROUP</div>
                      <div style={{ maxHeight: 280, overflowY: 'auto' }}>
                        <table className="tbl">
                          <thead><tr><th>ID</th><th>TOTAL</th><th>USED</th><th>AVAILABLE</th><th>STATUS</th></tr></thead>
                          <tbody>
                            {g.ids.map(id => {
                              const avail = id.totalStock - id.usedStock;
                              const p = id.totalStock > 0 ? id.usedStock / id.totalStock : 0;
                              const c = stockColor(id.usedStock, id.totalStock);
                              const s2 = p >= 0.9 ? 'LOW' : p >= 0.6 ? 'MID' : 'OK';
                              const b2 = p >= 0.9 ? 'badge-red' : p >= 0.6 ? 'badge-yellow' : 'badge-green';
                              return (
                                <tr key={id.id}>
                                  <td className="mono" style={{ color: '#9ba3cc' }}>{id.id}</td>
                                  <td className="mono">{fmtK(id.totalStock)}</td>
                                  <td className="mono" style={{ color: '#ffaa00' }}>{fmtK(id.usedStock)}</td>
                                  <td className="mono" style={{ color: c, fontWeight: 700 }}>{fmtK(avail)}</td>
                                  <td><span className={`badge ${b2}`}>{s2}</span></td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* ── NEW ORDER ── */}
        {activeTab === 'New Order' && (
          <div style={{ maxWidth: 580 }}>
            <div className="page-title" style={{ marginBottom: 20 }}>FULFILL CUSTOMER ORDER</div>
            <div className="card">
              <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <div className="lbl">CUSTOMER IN-GAME ID</div>
                  <input value={orderForm.customerGameId} onChange={e => setOrderForm(p => ({ ...p, customerGameId: e.target.value }))} placeholder="e.g. Player#1234" />
                </div>
                <div>
                  <div className="lbl">QUANTITY IN K (type 5 for 5K, 15 for 15K, 0.5 for 500)</div>
                  <input type="number" value={orderForm.quantity} onChange={e => setOrderForm(p => ({ ...p, quantity: e.target.value }))} placeholder="e.g. 5 = 5K popularity" />
                </div>

                <div style={S.previewBox}>
                  <div className="lbl" style={{ marginBottom: 8 }}>BEST ID TO USE FOR THIS ORDER</div>
                  {orderForm.quantity && parseFloat(orderForm.quantity) > 0 ? (() => {
                    const qty = parseFloat(orderForm.quantity) * 1000;
                    const best = getBest(qty);
                    return best ? (
                      <div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
                          <span className="mono" style={{ color: '#5b6fff', fontWeight: 700, fontSize: 16 }}>{best.id}</span>
                          <span style={{ color: '#4a5278', fontSize: 11, fontFamily: 'Space Mono, monospace' }}>from: {best.groupId}</span>
                        </div>
                        <div style={{ display: 'flex', gap: 24 }}>
                          <div><div className="lbl">AVAILABLE IN THIS ID</div><div className="mono" style={{ color: '#00e5a0', fontSize: 15 }}>{fmtK(best.totalStock - best.usedStock)}</div></div>
                          <div><div className="lbl">ORDER AMOUNT</div><div className="mono" style={{ color: '#fff', fontSize: 15 }}>{fmtK(qty)}</div></div>
                          <div><div className="lbl">EARNINGS</div><div className="mono" style={{ color: '#ffaa00', fontSize: 15 }}>{fmtMoney(qty * best.pricePerUnit)}</div></div>
                        </div>
                      </div>
                    ) : <span className="mono" style={{ color: '#ff4d4d', fontSize: 13 }}>⚠ No single ID has enough stock</span>;
                  })() : <span className="mono" style={{ color: '#2a3050', fontSize: 13 }}>Enter quantity to see recommendation</span>}
                </div>

                <button className="btn-primary btn-full" onClick={handleOrder}>⚡ FULFILL ORDER</button>
              </div>
            </div>

            {orderResult && (
              <div className="card" style={{ borderColor: '#00e5a030', marginTop: 16 }}>
                <div className="mono" style={{ color: '#00e5a0', fontWeight: 700, marginBottom: 16 }}>✓ ORDER FULFILLED & SAVED TO PC</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
                  {[
                    { l: 'ORDER ID', v: orderResult.order.id },
                    { l: 'CUSTOMER', v: orderResult.order.customerGameId },
                    { l: 'BULK ID USED', v: orderResult.order.bulkIdUsed, color: '#5b6fff' },
                    { l: 'QUANTITY', v: fmtK(orderResult.order.quantity) },
                    { l: 'EARNINGS', v: fmtMoney(orderResult.order.earnings), color: '#00e5a0' },
                    { l: 'DATE', v: orderResult.order.date },
                  ].map(f => (
                    <div key={f.l}>
                      <div className="lbl">{f.l}</div>
                      <div className="mono" style={{ fontSize: 14, color: f.color || '#e8eaf0' }}>{f.v}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* ── ORDER HISTORY ── */}
        {activeTab === 'Order History' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <div className="page-title">{orders.length} TOTAL ORDERS</div>
              <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                <input style={{ width: 260 }} value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by ID, customer, bulk ID..." />
                <button className="btn-outline" onClick={exportCSV}>⬇ Export CSV</button>
              </div>
            </div>

            <div style={S.grid4}>
              {[
                { label: 'TOTAL ORDERS', value: orders.length, color: '#5b6fff' },
                { label: 'TOTAL EARNED', value: fmtMoney(stats.totalEarnings), color: '#00e5a0' },
                { label: 'UNITS SOLD', value: fmtK(orders.reduce((a, o) => a + o.quantity, 0)), color: '#ffaa00' },
                { label: 'AVG ORDER SIZE', value: orders.length > 0 ? fmtK(Math.round(orders.reduce((a, o) => a + o.quantity, 0) / orders.length)) : '0', color: '#8b5cf6' },
              ].map(s => (
                <div key={s.label} className="stat-card">
                  <div className="lbl">{s.label}</div>
                  <div style={{ fontSize: 22, fontWeight: 800, color: s.color, fontFamily: 'Space Mono, monospace', marginTop: 6 }}>{s.value}</div>
                </div>
              ))}
            </div>

            <div className="card">
              <table className="tbl">
                <thead><tr><th>ORDER ID</th><th>CUSTOMER GAME ID</th><th>QTY</th><th>BULK ID USED</th><th>EARNINGS</th><th>DATE</th><th>STATUS</th></tr></thead>
                <tbody>
                  {filteredOrders.length === 0 && <tr><td colSpan={7} style={{ color: '#4a5278', textAlign: 'center' }}>No orders found.</td></tr>}
                  {filteredOrders.map(o => (
                    <tr key={o.id}>
                      <td className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{o.id}</td>
                      <td style={{ color: '#9ba3cc' }}>{o.customerGameId}</td>
                      <td className="mono" style={{ color: '#fff', fontWeight: 700 }}>{fmtK(o.quantity)}</td>
                      <td className="mono" style={{ color: '#8b5cf6', fontWeight: 700 }}>{o.bulkIdUsed}</td>
                      <td className="mono" style={{ color: '#00e5a0' }}>{fmtMoney(o.earnings)}</td>
                      <td className="mono" style={{ color: '#4a5278' }}>{o.date}</td>
                      <td><span className="badge badge-green">{o.status}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

const S = {
